// Aviso por e-mail quando um fluxo falha. Só nome do fluxo, id/link da execução, nó e mensagem de erro (cortada).
const e = $('Erro em um fluxo').first().json;
const cfg = $input.first().json;
const ex = e.execution || {};
const wf = e.workflow || {};
const err = ex.error || (e.trigger && e.trigger.error) || {};
const linhas = [
  'Um fluxo do n8n da Crystal falhou.',
  '',
  'Fluxo: ' + (wf.name || '?') + ' (' + (wf.id || '?') + ')',
  'Execução: ' + (ex.id || 'não guardada') + (ex.url ? ' · ' + ex.url : ''),
  'Último nó: ' + (ex.lastNodeExecuted || (err.node && err.node.name) || '?'),
  'Erro: ' + String(err.message || '').slice(0, 300),
  '',
  'O que fazer: abrir Executions no editor e ver o nó em vermelho. Se foi a API do app ou o Supabase, conferir se',
  'estão de pé (api./healthz). A conciliação das 06:10 e 18:10 reenvia à API os bloqueios que não chegaram.',
];
return [{ json: { para: cfg.equipe_email, assunto: '[n8n] Falha em ' + (wf.name || 'um fluxo'), texto: linhas.join('\n') } }];
